    static void processInput(InputReader in, PrintWriter out) {
        int totalCards = in.nextInt();
        int totalShuffles = in.nextInt();

        NumberTheory.Mod998 mod = new NumberTheory.Mod998();
        mod.fInv(totalCards + totalShuffles);

        long phaseSum = 1;
        long product = 1;
        for (int i = 0; product != 0; i++) {
            product = mod.mult(product, totalCards - i, mod.smallInv(totalShuffles + totalCards - i));
            phaseSum = mod.add(phaseSum, product);
        }

        long result = 0;
        for (int k = 1; k <= totalCards; k++) {
            result = mod.add(result, mod.mult(mod.paritySign(k + 1), mod.ncr(totalCards, k), totalShuffles + k, mod.smallInv(k), phaseSum));
        }
        out.println(result);
    }

    static class InputReader {
        BufferedReader br;
        StringTokenizer st;

        public InputReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
            st = null;
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
