#include <bits/stdc++.h>
using namespace std;

struct IntStack {
    std::vector<int> data;
    int size;

    IntStack() : data(8), size(0) {}

    void push(int val) {
        if (size >= (int)data.size()) {
            data.resize(data.size() * 2);
        }
        data[size++] = val;
    }

    int get(int index) {
        assert(index >= 0 && index < size);
        return data[index];
    }

    int getSize() {
        return size;
    }
};

struct NumberTheory {
    struct Mod998 {
        long long modulus() { return 998244353LL; }

        long long fact(int n, IntStack &factorials, IntStack &invFactorials) {
            while (factorials.getSize() <= n) {
                long long lastFact = factorials.get(factorials.getSize() - 1);
                factorials.push((int)((lastFact * factorials.getSize()) % modulus()));
            }
            return factorials.get(n);
        }

        long long fInv(int n, IntStack &factorials, IntStack &invFactorials) {
            int lastIdx = invFactorials.getSize() - 1;
            if (lastIdx < n) {
                std::vector<long long> invs(n - lastIdx);
                long long invFactN = mult(fact(n, factorials, invFactorials), modInverse(fact(n, factorials, invFactorials), modulus()));
                invs[0] = invFactN;
                for (int i = 1; i < (int)invs.size(); i++) {
                    invs[i] = mult(invs[i - 1], n - i + 1);
                }
                for (int i = (int)invs.size() - 1; i >= 0; i--) {
                    invFactorials.push((int)invs[i]);
                }
            }
            return invFactorials.get(n);
        }

        long long paritySign(long long k) {
            return (k & 1) ? modulus() - 1 : 1;
        }

        long long ncr(int n, int r, IntStack &factorials, IntStack &invFactorials) {
            if (n < 0 || r < 0 || n < r) return 0;
            return mult(fact(n, factorials, invFactorials), mult(fInv(r, factorials, invFactorials), fInv(n - r, factorials, invFactorials)));
        }

        long long smallInv(int n, IntStack &factorials, IntStack &invFactorials) {
            return mult(fInv(n, factorials, invFactorials), fact(n - 1, factorials, invFactorials));
        }

        long long add(long long a, long long b) {
            long long sum = a + b;
            return sum >= modulus() ? sum - modulus() : sum;
        }

        long long mult(long long a, long long b) {
            return (a * b) % modulus();
        }

        long long modInverse(long long a, long long m) {
            long long m0 = m, t, q;
            long long x0 = 0, x1 = 1;
            if (m == 1) return 0;
            while (a > 1) {
                q = a / m;
                t = m;
                m = a % m, a = t;
                t = x0;
                x0 = x1 - q * x0;
                x1 = t;
            }
            if (x1 < 0) x1 += m0;
            return x1;
        }
    };
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int totalCards, totalShuffles;
    cin >> totalCards >> totalShuffles;

    NumberTheory::Mod998 mod;
    IntStack factorials, invFactorials;
    factorials.push(1);
    invFactorials.push(1);

    long long modVal = mod.modulus();

    // Precompute inverse of totalCards + totalShuffles
    long long total = totalCards + totalShuffles;
    // No explicit use of this in the code, but assuming it's for some precomputation
    // as in the original code, so we can ignore it here.

    long long phaseSum = 1;
    long long product = 1;
    for (int i = 0; product != 0; i++) {
        long long denom = totalShuffles + totalCards - i;
        long long invDenom = mod.modInverse(denom, modVal);
        product = mod.mult(product, totalCards - i, invDenom);
        phaseSum = mod.add(phaseSum, product);
        if (totalCards - i == 0) break; // prevent infinite loop if product becomes 0
    }

    long long result = 0;
    for (int k = 1; k <= totalCards; k++) {
        long long sign = mod.paritySign(k + 1);
        long long nCr = mod.ncr(totalCards, k, factorials, invFactorials);
        long long invK = mod.modInverse(k, modVal);
        long long term = mod.mult(sign, nCr, totalShuffles + k, invK, phaseSum);
        result = mod.add(result, term);
    }

    cout << result << "\n";

    return 0;
}

